// SEARCH
TreeNode* walk = root;
while (walk && walk->val != t)
    walk = (t < walk->val) ? walk->left : walk->right;

// INSERT (attach as new leaf)
if (!root) return new TreeNode(v);
TreeNode* cur = root;
while (true) {
    if (v < cur->val) {
        if (!cur->left) { cur->left = new TreeNode(v); break; }
        cur = cur->left;
    } else { /* mirror right */ }
}

// MIN / MAX
while (cur->left)  cur = cur->left;   // min
while (cur->right) cur = cur->right;  // max

